//! End-to-end notification scenarios (WBE-223 ticket scenarios 3 and 5),
//! bridged by the direct-message flow: every notification the model knows
//! is generated by its real action over HTTP and reads back through
//! `GET /api/v1/notifications` under its type filters and id cursors; the
//! grouped `GET /api/v2/notifications` collapses one status's favourites,
//! boosts and reactions into counted groups and keeps every other type on
//! its own `ungrouped-<id>` key while `unread_count` tracks the undismissed
//! rows through dismissal and clear; `GET`/`POST /api/v1/markers`
//! round-trips the read positions that drive that count;
//! `PUT /api/pleroma/notification_settings` gates a stranger's favourite
//! and mention while the exempt follow request still lands; a `direct`
//! post @-mentioning two local users threads one conversation all three
//! read, reply into and withdraw from; and two local users exchange chats
//! whose per-peer unread counts agree until the chat's own read endpoint
//! empties them, with a third user locked out of the pair entirely.
//!
//! Where the area files (`notification_generation.rs`, `notifications.rs`,
//! `notifications_v2.rs`, `markers.rs`, `conversations.rs`, `chats.rs`)
//! pin each endpoint's own refusals — seeding rows through the model in
//! some of them — this module builds every fact through the client API
//! exactly as a real client does: post, follow, favourite, boost, react,
//! lock an account so a follow turns into a request, mention, DM, chat —
//! and then observes the composite flows across the v1/v2 lists, the
//! markers, the settings gate, the conversations and the chats.

#![cfg(test)]

use axum::{Router, http::StatusCode};
use serde_json::{Value, json};
use sqlx::PgPool;
use uuid::Uuid;
use wired_be::models::user::User;

use crate::common;

/// The scopes every scenario actor carries: the root `read` and `write`
/// cover every sub-scope the journeys touch (decision 9's scope tree).
const SCOPES: &str = "read write";
/// The flat notification listing and its dismissal routes.
const V1: &str = "/api/v1/notifications";
/// The grouped notification listing and its `unread_count` companion.
const V2: &str = "/api/v2/notifications";
/// Pleroma's mark-seen route.
const PLEROMA_READ: &str = "/api/pleroma/notifications/read";
/// The read-marker routes.
const MARKERS: &str = "/api/v1/markers";
/// A `GET /api/v1/markers` asking for both timelines, spelled like an
/// array-parameter client.
const BOTH_TIMELINES: &str = "?timeline%5B%5D=home&timeline%5B%5D=notifications";
/// The same asking for `notifications` alone.
const NOTIFICATIONS_TIMELINE: &str = "?timeline%5B%5D=notifications";
/// The Pleroma notification-settings route.
const SETTINGS: &str = "/api/pleroma/notification_settings";
/// The status create route every action seeds from.
const STATUSES: &str = "/api/v1/statuses";
/// The account routes: the follow write and `update_credentials`.
const ACCOUNTS: &str = "/api/v1/accounts";
/// The Pleroma status route the reaction write lives under.
const PLEROMA_STATUSES: &str = "/api/v1/pleroma/statuses";
/// The Mastodon conversation routes.
const CONVERSATIONS: &str = "/api/v1/conversations";
/// Pleroma's conversation routes.
const PLEROMA_CONVERSATIONS: &str = "/api/v1/pleroma/conversations";
/// The Pleroma chat routes.
const CHATS: &str = "/api/v1/pleroma/chats";
/// The paged twin of the chat list.
const CHATS_V2: &str = "/api/v2/pleroma/chats";
/// A thumbs-up and its percent-encoded path segment.
const THUMB: &str = "👍";
const THUMB_SEGMENT: &str = "%F0%9F%91%8D";
/// A party popper and its segment.
const PARTY: &str = "🎉";
const PARTY_SEGMENT: &str = "%F0%9F%8E%89";
/// A heart and its segment.
const HEART: &str = "❤️";
const HEART_SEGMENT: &str = "%E2%9D%A4%EF%B8%8F";
/// The shared 404 body of the notification, conversation and chat gates.
const NOT_FOUND: &str = "Record not found";
/// A flat-page telling as a `(type, actor id, status id)` triple.
type Telling = (String, String, Option<String>);

/// A local user named `nickname` beside a bearer token granting `SCOPES`.
async fn user(pool: &PgPool, nickname: &str) -> (User, String) {
    let created = common::create_local_user(pool, nickname).await;
    let token = common::create_app_and_token(pool, &created, SCOPES).await;
    (created, token)
}

/// The `id` of a rendered entity, as its JSON spells it.
fn entity_id(entity: &Value) -> String {
    entity["id"]
        .as_str()
        .expect("the entity carries its id")
        .to_owned()
}

/// The `id` strings of rendered entities, in answer order.
fn ids_of(rows: &[Value]) -> Vec<String> {
    rows.iter().map(entity_id).collect()
}

/// The `GET` of `path` as `token`, asserted 200 and answered as JSON.
async fn got(app: &Router, token: &str, path: &str) -> Value {
    let response = common::TestRequest::get(path).bearer(token).send(app).await;
    common::assert_answer(&response, StatusCode::OK, &format!("GET {path}"));
    response.json_value()
}

/// The `GET` of `path` as `token`, asserted 200 and answered as a JSON
/// array of entities.
async fn got_array(app: &Router, token: &str, path: &str) -> Vec<Value> {
    got(app, token, path)
        .await
        .as_array()
        .expect("the endpoint answers a JSON array")
        .clone()
}

/// The `POST` of the JSON `body` to `path` as `token`, asserted 200 and
/// answered.
async fn posted(app: &Router, token: &str, path: &str, body: &Value) -> Value {
    let response = common::TestRequest::post(path)
        .bearer(token)
        .json(body)
        .send(app)
        .await;
    common::assert_answer(&response, StatusCode::OK, &format!("POST {path}"));
    response.json_value()
}

/// The body-less `POST` to `path` as `token`, asserted 200 and answered.
async fn acted(app: &Router, token: &str, path: &str) -> Value {
    let response = common::TestRequest::post(path)
        .bearer(token)
        .send(app)
        .await;
    common::assert_answer(&response, StatusCode::OK, &format!("POST {path}"));
    response.json_value()
}

/// The `DELETE` of `path` as `token`, asserted 200 and answered.
async fn withdrawn(app: &Router, token: &str, path: &str) -> Value {
    let response = common::TestRequest::delete(path)
        .bearer(token)
        .send(app)
        .await;
    common::assert_answer(&response, StatusCode::OK, &format!("DELETE {path}"));
    response.json_value()
}

/// A plain public `POST /api/v1/statuses` of `text` as `token`.
async fn post(app: &Router, token: &str, text: &str) -> Value {
    posted(app, token, STATUSES, &json!({ "status": text })).await
}

/// A `direct` `POST /api/v1/statuses` of `text` as `token`.
async fn direct_post(app: &Router, token: &str, text: &str) -> Value {
    posted(
        app,
        token,
        STATUSES,
        &json!({ "status": text, "visibility": "direct" }),
    )
    .await
}

/// The `POST /api/v1/accounts/{target}/follow`, answered as the
/// relationship entity it wrote.
async fn follow(app: &Router, token: &str, target: &str) -> Value {
    acted(app, token, &format!("{ACCOUNTS}/{target}/follow")).await
}

/// The body-less `POST /api/v1/statuses/{id}/{verb}` (`favourite`, `reblog`
/// and their twins), answered as the status entity.
async fn status_action(app: &Router, token: &str, id: &str, verb: &str) -> Value {
    acted(app, token, &format!("{STATUSES}/{id}/{verb}")).await
}

/// The `PUT /api/v1/pleroma/statuses/{id}/reactions/{segment}` write,
/// answered as the status entity.
async fn react(app: &Router, token: &str, id: &str, segment: &str) -> Value {
    let path = format!("{PLEROMA_STATUSES}/{id}/reactions/{segment}");
    let response = common::TestRequest::put(&path)
        .bearer(token)
        .send(app)
        .await;
    common::assert_answer(&response, StatusCode::OK, "the reaction stores");
    response.json_value()
}

/// Locks `token`'s own account through `update_credentials`, so a later
/// follow of it waits as a request — the HTTP spelling of the ticket's
/// "edit follow into a request".
async fn lock_account(app: &Router, token: &str) {
    let response = common::TestRequest::patch(&format!("{ACCOUNTS}/update_credentials"))
        .bearer(token)
        .json(&json!({ "locked": true }))
        .send(app)
        .await;
    common::assert_answer(&response, StatusCode::OK, "the self-lock");
    assert_eq!(
        response.json_value()["locked"],
        json!(true),
        "the answer states the flag"
    );
}

/// `PUT /api/pleroma/notification_settings` blocking (or unblocking)
/// strangers, asserted against the module's `{"status":"success"}` answer.
async fn gate_strangers(app: &Router, token: &str, blocked: bool) {
    let response = common::TestRequest::put(SETTINGS)
        .bearer(token)
        .json(&json!({ "block_from_strangers": blocked }))
        .send(app)
        .await;
    common::assert_answer(&response, StatusCode::OK, "the settings write");
    assert_eq!(
        response.json_value(),
        json!({ "status": "success" }),
        "the settings answer"
    );
}

/// The caller's flat notification page under `query`, as entities.
async fn flat(app: &Router, token: &str, query: &str) -> Vec<Value> {
    got_array(app, token, &format!("{V1}{query}")).await
}

/// A page as `(type, actor id, status id)` triples.
fn told(rows: &[Value]) -> Vec<Telling> {
    rows.iter()
        .map(|row| {
            (
                row["type"].as_str().expect("a type").to_owned(),
                row["account"]["id"]
                    .as_str()
                    .expect("an actor id")
                    .to_owned(),
                row["status"]["id"].as_str().map(str::to_owned),
            )
        })
        .collect()
}

/// Triples (or ids) sorted for order-insensitive comparison.
fn sorted<T: Ord>(mut values: Vec<T>) -> Vec<T> {
    values.sort();
    values
}

/// One expected telling: `kind` by `actor`, about `status` when named.
fn telling(kind: &str, actor: &str, status: Option<&str>) -> Telling {
    (kind.to_owned(), actor.to_owned(), status.map(str::to_owned))
}

/// The row of a page carrying `wanted`'s type, for the per-row probes.
fn row_of<'a>(rows: &'a [Value], wanted: &str) -> &'a Value {
    rows.iter()
        .find(|row| row["type"].as_str() == Some(wanted))
        .unwrap_or_else(|| panic!("the page has no `{wanted}` row: {rows:?}"))
}

/// The ids are strictly descending — the flat listing's own key
/// (decision 4).
fn assert_descending(ids: &[String]) {
    for pair in ids.windows(2) {
        assert_eq!(pair.len(), 2, "a window of two ids is a pair");
        assert!(pair[0] > pair[1], "newest row first, got {ids:?}");
    }
}

/// The grouped listing under `query`, answered raw.
async fn grouped(app: &Router, token: &str, query: &str) -> Value {
    got(app, token, &format!("{V2}{query}")).await
}

/// The `notification_groups` of a grouped body, as values.
fn groups(body: &Value) -> Vec<Value> {
    body["notification_groups"]
        .as_array()
        .expect("notification_groups is a list")
        .clone()
}

/// The `GET {V2}/unread_count` answer.
async fn unread(app: &Router, token: &str) -> i64 {
    got(app, token, &format!("{V2}/unread_count")).await["count"]
        .as_i64()
        .expect("the count is a number")
}

/// The `{}` answer of the caller's `POST {V1}/clear`.
async fn clear(app: &Router, token: &str) {
    assert_eq!(
        acted(app, token, &format!("{V1}/clear")).await,
        json!({}),
        "the clear answers the empty object"
    );
}

/// The `{}` answer of the `POST {V1}/{id}/dismiss` for one notification.
async fn dismiss(app: &Router, token: &str, id: &str) {
    assert_eq!(
        acted(app, token, &format!("{V1}/{id}/dismiss")).await,
        json!({}),
        "the dismissal answers the empty object"
    );
}

// ─────────────────  Scenario (1): every type, the flat page  ─────────────────

/// The scenario 1 seed: every action that ends in a telling, performed
/// over HTTP by its own actor, and the facts the recipient's flat listing
/// must therefore answer.
#[derive(Debug)]
struct Mixed {
    /// Alice's token: the recipient of seven tellings of six types.
    alice: String,
    /// Eve's token: the locked account told only of the pending request.
    eve: String,
    /// Bob's account id.
    bob: String,
    /// Carol's account id.
    carol: String,
    /// Dave's account id.
    dave: String,
    /// The id of alice's post — favourited twice, boosted, reacted to.
    subject: String,
    /// The id of carol's mentioning post.
    carol_post: String,
    /// The id of dave's mentioning post.
    dave_post: String,
    /// Alice's inbox as sorted tellings.
    want: Vec<Telling>,
}

/// Performs every action of scenario 1 through `app`: a follow, two
/// favourites of one post, a boost, a reaction, two mentions from
/// different accounts, alice's own self-like and self-reaction (which
/// must tell nobody), and — after locking eve through the profile edit —
/// a follow of her that waits as a request.
async fn mix(app: &Router, pool: &PgPool) -> Mixed {
    let (alice, alice_token) = user(pool, "alice").await;
    let (bob, bob_token) = user(pool, "bob").await;
    let (carol, carol_token) = user(pool, "carol").await;
    let (dave, dave_token) = user(pool, "dave").await;
    let (eve, eve_token) = user(pool, "eve").await;
    let subject = entity_id(&post(app, &alice_token, "tell me everything").await);

    let granted = follow(app, &bob_token, &alice.id.to_string()).await;
    assert_eq!(
        granted["following"],
        json!(true),
        "an unlocked account grants the follow: {granted}"
    );
    let _liked = status_action(app, &bob_token, &subject, "favourite").await;
    let _boosted = status_action(app, &carol_token, &subject, "reblog").await;
    let _reacted = react(app, &bob_token, &subject, THUMB_SEGMENT).await;
    let carol_post = entity_id(&post(app, &carol_token, "hello @alice").await);
    let dave_post = entity_id(&post(app, &dave_token, "@alice, once more").await);
    let _also_liked = status_action(app, &dave_token, &subject, "favourite").await;

    // The self-actions an open inbox must stay silent about.
    let _own_like = status_action(app, &alice_token, &subject, "favourite").await;
    let _own_reaction = react(app, &alice_token, &subject, PARTY_SEGMENT).await;

    // A follow of an account edited into a locked one waits as a request.
    lock_account(app, &eve_token).await;
    let waiting = follow(app, &bob_token, &eve.id.to_string()).await;
    assert_eq!(
        waiting["requested"],
        json!(true),
        "the locked account turns the follow into a request: {waiting}"
    );

    let bob_id = bob.id.to_string();
    let carol_id = carol.id.to_string();
    let dave_id = dave.id.to_string();
    let want = sorted(vec![
        telling("favourite", &bob_id, Some(&subject)),
        telling("favourite", &dave_id, Some(&subject)),
        telling("follow", &bob_id, None),
        telling("mention", &carol_id, Some(&carol_post)),
        telling("mention", &dave_id, Some(&dave_post)),
        telling("pleroma:emoji_reaction", &bob_id, Some(&subject)),
        telling("reblog", &carol_id, Some(&subject)),
    ]);
    Mixed {
        alice: alice_token,
        eve: eve_token,
        bob: bob_id,
        carol: carol_id,
        dave: dave_id,
        subject,
        carol_post,
        dave_post,
        want,
    }
}

/// Every type the model produces is generated by its real action and
/// shows up for the recipient in `GET /api/v1/notifications`: seven rows
/// on a mixed page naming the right actor and status — `follow`, `mention`,
/// `favourite`, `reblog` and `pleroma:emoji_reaction` with its emoji and
/// stored group key — alice's self-actions told to nobody, and eve's
/// locked inbox holding exactly the `follow_request`.
#[tokio::test]
async fn every_action_tells_the_recipient_in_the_flat_listing() {
    let db = common::test_db().await;
    let pool = db.pool().clone();
    let app = common::test_app(pool.clone());
    let seed = mix(&app, &pool).await;

    let rows = flat(&app, &seed.alice, "").await;
    assert_eq!(
        sorted(told(&rows)),
        seed.want,
        "six actions of five types told alice, each exactly once"
    );
    assert_descending(&ids_of(&rows));

    let reaction = row_of(&rows, "pleroma:emoji_reaction");
    assert_eq!(
        reaction["emoji"],
        json!(THUMB),
        "the telling carries the emoji"
    );
    assert_eq!(
        reaction["group_key"],
        json!(format!("pleroma:emoji_reaction-{}-{THUMB}", seed.subject)),
        "and the key its group will read under"
    );
    assert_eq!(
        reaction["pleroma"]["is_seen"],
        json!(false),
        "a fresh telling is unseen"
    );
    let follow_row = row_of(&rows, "follow");
    assert_eq!(
        follow_row["group_key"],
        json!(format!("ungrouped-{}", entity_id(follow_row))),
        "an ungrouped row carries its unique key"
    );
    assert!(
        follow_row.get("status").is_none(),
        "and names no status: {follow_row}"
    );

    assert_eq!(
        told(&flat(&app, &seed.eve, "").await),
        vec![telling("follow_request", &seed.bob, None)],
        "eve is told the pending request — and nothing else"
    );
}

/// On the mixed page, `types[]` keeps only the named types and
/// `exclude_types[]` removes the named ones — each probe over the same
/// seven-row page [`mix`] seeded.
#[tokio::test]
async fn the_flat_page_honors_its_type_filters() {
    let db = common::test_db().await;
    let pool = db.pool().clone();
    let app = common::test_app(pool.clone());
    let seed = mix(&app, &pool).await;
    let owed = |kind: &str, actor: &str| telling(kind, actor, Some(&seed.subject));

    assert_eq!(
        flat(&app, &seed.alice, "").await.len(),
        7,
        "seven tellings on the page"
    );
    let kept = sorted(told(
        &flat(
            &app,
            &seed.alice,
            "?types[]=favourite&types[]=pleroma:emoji_reaction",
        )
        .await,
    ));
    assert_eq!(
        kept,
        sorted(vec![
            owed("favourite", &seed.bob),
            owed("favourite", &seed.dave),
            owed("pleroma:emoji_reaction", &seed.bob),
        ]),
        "types[] keeps exactly the named rows"
    );
    let mentions = sorted(told(&flat(&app, &seed.alice, "?types[]=mention").await));
    assert_eq!(
        mentions,
        sorted(vec![
            telling("mention", &seed.carol, Some(&seed.carol_post)),
            telling("mention", &seed.dave, Some(&seed.dave_post)),
        ]),
        "and the mentions are their own keep"
    );
    let dropped = sorted(told(
        &flat(
            &app,
            &seed.alice,
            "?exclude_types[]=mention&exclude_types[]=follow",
        )
        .await,
    ));
    assert_eq!(
        dropped,
        sorted(vec![
            owed("favourite", &seed.bob),
            owed("favourite", &seed.dave),
            owed("pleroma:emoji_reaction", &seed.bob),
            owed("reblog", &seed.carol),
        ]),
        "exclude_types[] drops the two mentions and the follow"
    );
}

/// On the mixed page the `min_id`/`max_id`/`since_id` cursors walk the id
/// order (decision 4): `max_id` older, `since_id` newer, `min_id` read
/// forward and answered flipped, an exhausted walk empty, `limit` cutting
/// the head — all keyed on the ids the unfiltered page itself reported.
#[tokio::test]
async fn the_flat_page_walks_its_id_cursors() {
    let db = common::test_db().await;
    let pool = db.pool().clone();
    let app = common::test_app(pool.clone());
    let seed = mix(&app, &pool).await;

    let full = ids_of(&flat(&app, &seed.alice, "").await);
    assert_eq!(full.len(), 7, "seven tellings on the page");
    let page = |query: String| {
        let application = app.clone();
        let token = seed.alice.clone();
        async move { ids_of(&flat(&application, &token, &query).await) }
    };

    assert_eq!(
        page("?limit=3".to_owned()).await,
        full[0..3],
        "limit cuts the newest head of the page"
    );
    assert_eq!(
        page(format!("?max_id={}", full[3])).await,
        full[4..7],
        "max_id keeps strictly older rows"
    );
    assert_eq!(
        page(format!("?since_id={}", full[3])).await,
        full[0..3],
        "since_id keeps the newer rows, newest first"
    );
    assert_eq!(
        page(format!("?min_id={}&limit=2", full[3])).await,
        vec![full[1].clone(), full[2].clone()],
        "a min_id page reads forward and answers flipped"
    );
    assert!(
        page(format!("?max_id={}", full[6])).await.is_empty(),
        "older than the oldest row answers nothing"
    );
}

// ─────────────────  Scenario (2): the v2 grouped listing  ─────────────────

/// One group the v2 listing must answer, derived row by row from the
/// recipient's own flat page: the key, the counted members, the bounds
/// the page walks, the newest-first deduplicated samples and the status.
#[derive(Debug)]
struct ExpectedGroup {
    /// The group key (`<type>-<status>[-<emoji>]` or `ungrouped-<id>`).
    key: String,
    /// The group's notification type.
    kind: String,
    /// How many flat rows merged into it.
    count: i64,
    /// Its newest member's notification id.
    most_recent: String,
    /// Its oldest member's notification id.
    page_min: String,
    /// The member actors, newest first, each named once.
    samples: Vec<String>,
    /// The status the group names, if any.
    status_id: Option<String>,
}

/// Collapses a newest-first flat page into the groups the v2 listing must
/// answer: first-seen group order is exactly the grouped listing's walk of
/// `most_recent_notification_id` values (one page carries a whole group,
/// so its newest member is seen first).
fn expected_groups(rows: &[Value]) -> Vec<ExpectedGroup> {
    let mut listed: Vec<ExpectedGroup> = Vec::new();
    for row in rows {
        let key = row["group_key"].as_str().expect("every entity has a key");
        let actor = row["account"]["id"]
            .as_str()
            .expect("an actor id")
            .to_owned();
        let id = entity_id(row);
        match listed.iter_mut().find(|group| group.key == key) {
            Some(group) => {
                group.count += 1;
                group.page_min = id;
                if !group.samples.contains(&actor) {
                    group.samples.push(actor);
                }
            }
            None => listed.push(ExpectedGroup {
                key: key.to_owned(),
                kind: row["type"].as_str().expect("a type").to_owned(),
                count: 1,
                most_recent: id.clone(),
                page_min: id,
                samples: vec![actor],
                status_id: row["status"]["id"].as_str().map(str::to_owned),
            }),
        }
    }
    listed
}

/// Compares a v2 page's groups with the expected table entry by entry:
/// keys, types, counts, bounds and samples.
fn assert_groups(listed: &[Value], want: &[ExpectedGroup]) {
    assert_eq!(listed.len(), want.len(), "one group per key");
    for (entry, expected) in listed.iter().zip(want) {
        assert_eq!(entry["group_key"], expected.key, "the key {expected:?}");
        assert_eq!(entry["type"], expected.kind, "the type of {expected:?}");
        assert_eq!(
            entry["notifications_count"], expected.count,
            "every member collapsed into one counted group"
        );
        assert_eq!(
            entry["most_recent_notification_id"], expected.most_recent,
            "the group's newest member"
        );
        assert_eq!(entry["page_min_id"], expected.page_min, "its oldest");
        assert_eq!(
            entry["page_max_id"], expected.most_recent,
            "and one grouped page carries the whole group"
        );
        assert_eq!(
            entry["sample_account_ids"],
            json!(expected.samples),
            "samples newest first, each actor once"
        );
        match &expected.status_id {
            Some(status) => {
                assert_eq!(entry["status_id"], json!(status), "the group's status");
            }
            None => assert!(
                entry.get("status_id").is_none(),
                "a status-less group omits the key: {entry}"
            ),
        }
    }
}

/// The recipient's two views of the same inbox: the newest-first flat page
/// and the groups the v2 listing must answer for it, re-read as one step
/// (the listing and its expectation always come from the same moment).
async fn pages(app: &Router, token: &str) -> (Vec<Value>, Vec<ExpectedGroup>) {
    let rows = flat(app, token, "").await;
    let expected = expected_groups(&rows);
    (rows, expected)
}

/// The ids of the two posts [`seed_grouped`] had alice publish: the
/// thrice-favourited, twice-boosted one and the singly-favourited one.
#[derive(Debug)]
struct Posts {
    /// The status every groupable telling piles onto.
    first: String,
    /// The lone favourite's status.
    second: String,
}

/// Seeds the grouped inbox of alice over HTTP: three favourites, two
/// boosts, two party reactions and one heart on her first post, a lone
/// favourite of a second account on her second post, and an ungrouped
/// follow by that account.
async fn seed_grouped(app: &Router, pool: &PgPool, alice: &User, alice_token: &str) -> Posts {
    let first = entity_id(&post(app, alice_token, "merge me").await);
    let second = entity_id(&post(app, alice_token, "one fan only").await);
    let (_bob, bob_token) = user(pool, "bob").await;
    let (_carol, carol_token) = user(pool, "carol").await;
    let (_dave, dave_token) = user(pool, "dave").await;
    let (_erin, erin_token) = user(pool, "erin").await;
    for token in [&bob_token, &carol_token, &dave_token] {
        let _liked = status_action(app, token, &first, "favourite").await;
    }
    for token in [&bob_token, &carol_token] {
        let _boosted = status_action(app, token, &first, "reblog").await;
    }
    for token in [&bob_token, &carol_token] {
        let _partied = react(app, token, &first, PARTY_SEGMENT).await;
    }
    let _hearted = react(app, &dave_token, &first, HEART_SEGMENT).await;
    let _lone = status_action(app, &erin_token, &second, "favourite").await;
    let _followed = follow(app, &erin_token, &alice.id.to_string()).await;
    Posts { first, second }
}

/// The v2 list collapses one status's favourites, boosts and reactions
/// into counted groups keyed `favourite-<id>`, `reblog-<id>` and
/// `pleroma:emoji_reaction-<id>-<emoji>` (one key per emoji), leaves the
/// follow alone on its `ungrouped-<id>` key, and lets `unread_count` track
/// every undismissed row until a dismissal steps the count (and its
/// group) down and `POST {V1}/clear` empties both listings.
#[tokio::test]
async fn the_grouped_listing_collapses_one_status_and_counts_unread() {
    let db = common::test_db().await;
    let pool = db.pool().clone();
    let app = common::test_app(pool.clone());
    let (alice, alice_token) = user(&pool, "alice").await;
    let posts = seed_grouped(&app, &pool, &alice, &alice_token).await;

    let (rows, want) = pages(&app, &alice_token).await;
    assert_groups(&groups(&grouped(&app, &alice_token, "").await), &want);
    assert_group_keys(&rows, &want, &posts);

    assert_eq!(
        unread(&app, &alice_token).await,
        i64::try_from(rows.len()).expect("a page fits"),
        "every undismissed row counts while nothing is read away"
    );
    let merged = find_group(&want, &format!("favourite-{}", posts.first));
    assert_eq!(merged.count, 3, "three favourites of one status merged");
    dismiss(&app, &alice_token, &merged.page_min).await;

    let (left, again) = pages(&app, &alice_token).await;
    assert_groups(&groups(&grouped(&app, &alice_token, "").await), &again);
    assert_eq!(
        unread(&app, &alice_token).await,
        i64::try_from(left.len()).expect("a page fits"),
        "the undismissed rows still equal the count, one fewer"
    );
    assert_eq!(
        find_group(&again, &format!("favourite-{}", posts.first)).count,
        2,
        "the dismissed member left the group"
    );

    clear(&app, &alice_token).await;
    assert!(
        flat(&app, &alice_token, "").await.is_empty(),
        "the flat page cleared"
    );
    assert!(
        groups(&grouped(&app, &alice_token, "").await).is_empty(),
        "and the grouped one with it"
    );
    assert_eq!(
        unread(&app, &alice_token).await,
        0,
        "nothing undismissed is left"
    );
}

/// The group keys the page must carry: the stored `favourite-`/`reblog-`/
/// `pleroma:emoji_reaction-` keys (the emoji appended for reactions) for
/// `posts`, and the follow's derived `ungrouped-<id>`.
fn assert_group_keys(rows: &[Value], want: &[ExpectedGroup], posts: &Posts) {
    let keys = sorted(
        want.iter()
            .map(|group| group.key.clone())
            .collect::<Vec<String>>(),
    );
    assert_eq!(
        keys,
        sorted(vec![
            format!("favourite-{}", posts.first),
            format!("reblog-{}", posts.first),
            format!("pleroma:emoji_reaction-{}-{PARTY}", posts.first),
            format!("pleroma:emoji_reaction-{}-{HEART}", posts.first),
            format!("favourite-{}", posts.second),
            format!("ungrouped-{}", entity_id(row_of(rows, "follow"))),
        ]),
        "the groupable types key on the status (and the emoji); the \
         follow keeps its unique ungrouped key"
    );
}

/// The expected group `key` names, or a test panic.
fn find_group<'a>(want: &'a [ExpectedGroup], key: &str) -> &'a ExpectedGroup {
    want.iter()
        .find(|group| group.key == key)
        .unwrap_or_else(|| panic!("no group {key} on the page: {want:?}"))
}

// ───────────────────  Scenario (3): markers  ───────────────────

/// Seeds alice's three-telling inbox over HTTP (a favourite, a boost and a
/// mention) and answers the subject id beside the flat page's ids, newest
/// first.
async fn seed_three(app: &Router, pool: &PgPool, alice_token: &str) -> (String, Vec<String>) {
    let subject = entity_id(&post(app, alice_token, "mark me").await);
    let (_bob, bob_token) = user(pool, "bob").await;
    let (_carol, carol_token) = user(pool, "carol").await;
    let (_dave, dave_token) = user(pool, "dave").await;
    let _liked = status_action(app, &bob_token, &subject, "favourite").await;
    let _boosted = status_action(app, &carol_token, &subject, "reblog").await;
    let _mentioned = post(app, &dave_token, "@alice the third").await;
    (subject, ids_of(&flat(app, alice_token, "").await))
}

/// The `POST /api/v1/markers` answer for the `subject` home position and
/// the `oldest` notifications position: two markers, version `0`, `home`
/// unread-free by Pleroma's rule and `notifications` counting the two
/// unseen rows that stand past the position.
fn assert_written_markers(written: &Value, subject: &str, oldest: &str) {
    assert_eq!(
        written["home"],
        json!({
            "last_read_id": subject,
            "version": 0,
            "updated_at": written["home"]["updated_at"],
            "pleroma": { "unread_count": 0 },
        }),
        "home round-trips its position and has no unread concept: {written}"
    );
    assert_eq!(
        written["notifications"]["last_read_id"],
        json!(oldest),
        "notifications round-trips"
    );
    assert_eq!(written["notifications"]["version"], 0, "a first marker");
    assert_eq!(
        written["notifications"]["pleroma"]["unread_count"], 2,
        "the two unseen rows past the position"
    );
}

/// `POST /api/v1/markers` writes the notifications and home positions and
/// `GET` reads exactly that object back — `last_read_id`, `version` and
/// Pleroma's `pleroma.unread_count` — and the notifications position is
/// the marker the v2 `unread_count` reads through: unseen rows past it
/// count in both places, marking them seen with Pleroma's `read` takes
/// both to zero, and a rewrite bumps the version.
#[tokio::test]
async fn markers_round_trip_and_drive_the_unread_linkage() {
    let db = common::test_db().await;
    let pool = db.pool().clone();
    let app = common::test_app(pool.clone());
    let (_alice, alice_token) = user(&pool, "alice").await;
    let (subject, ids) = seed_three(&app, &pool, &alice_token).await;
    let oldest = ids[2].clone();

    assert_eq!(
        got(&app, &alice_token, &format!("{MARKERS}{BOTH_TIMELINES}")).await,
        json!({}),
        "an account that marked nothing has no markers"
    );
    let written = posted(
        &app,
        &alice_token,
        MARKERS,
        &json!({
            "home": { "last_read_id": subject },
            "notifications": { "last_read_id": oldest },
        }),
    )
    .await;
    assert_written_markers(&written, &subject, &oldest);
    assert_eq!(
        unread(&app, &alice_token).await,
        2,
        "and the v2 count reads through the very same marker"
    );
    assert_eq!(
        got(&app, &alice_token, &format!("{MARKERS}{BOTH_TIMELINES}")).await,
        written,
        "the GET answers exactly what the POST wrote"
    );

    let read = posted(&app, &alice_token, PLEROMA_READ, &json!({ "id": ids[0] })).await;
    assert_eq!(
        read["pleroma"]["is_seen"],
        json!(true),
        "Pleroma's read answers the newest notification, seen now"
    );
    assert_eq!(
        unread(&app, &alice_token).await,
        0,
        "the v2 count fell to nothing"
    );
    let notes = got(
        &app,
        &alice_token,
        &format!("{MARKERS}{NOTIFICATIONS_TIMELINE}"),
    )
    .await;
    assert_eq!(
        notes["notifications"]["pleroma"]["unread_count"], 0,
        "and so did the marker's own, with no unseen row left"
    );

    let moved = posted(
        &app,
        &alice_token,
        MARKERS,
        &json!({ "notifications": { "last_read_id": ids[1] } }),
    )
    .await;
    assert_eq!(
        moved["notifications"]["version"], 1,
        "a rewrite bumps the version"
    );
    assert_eq!(
        moved["notifications"]["last_read_id"],
        json!(&ids[1]),
        "and moves the position"
    );
}

/// The read positions the DM surfaces keep outside the markers table also
/// move through their own endpoints: `POST /api/v1/conversations/{id}/read`
/// flips the participation's flag, and `POST /api/v1/pleroma/chats/{id}/read`
/// walks the chat's unread references behind the posted `last_read_id`.
#[tokio::test]
async fn the_chat_and_conversation_reads_move_their_own_markers() {
    let db = common::test_db().await;
    let pool = db.pool().clone();
    let app = common::test_app(pool.clone());
    let (alice, alice_token) = user(&pool, "alice").await;
    let (bob, bob_token) = user(&pool, "bob").await;

    let _dm = direct_post(&app, &alice_token, "@bob read me").await;
    let owed = entity_id(&got_array(&app, &bob_token, CONVERSATIONS).await.remove(0));
    assert!(
        listed_unread(&app, &bob_token).await,
        "the fresh DM stands unread"
    );
    let _read = acted(&app, &bob_token, &format!("{CONVERSATIONS}/{owed}/read")).await;
    assert!(
        !listed_unread(&app, &bob_token).await,
        "the read endpoint moved the flag"
    );

    let hers = entity_id(&open_chat(&app, &alice_token, &bob.id.to_string()).await);
    let his = entity_id(&open_chat(&app, &bob_token, &alice.id.to_string()).await);
    let _first = send_message(&app, &alice_token, &hers, "ping").await;
    assert_eq!(
        chat_unread(&app, &bob_token, &his).await,
        1,
        "one message owed"
    );
    let refs = ids_of(&chat_messages(&app, &bob_token, &his).await);
    let marked = posted(
        &app,
        &bob_token,
        &format!("{CHATS}/{his}/read"),
        &json!({ "last_read_id": refs[0] }),
    )
    .await;
    assert_eq!(
        marked["unread"],
        json!(0),
        "the read answers the emptied chat"
    );
    assert_eq!(
        chat_unread(&app, &bob_token, &his).await,
        0,
        "the marker moved and the count followed"
    );
}

// ────────────────  Scenario (4): notification settings  ────────────────

/// `PUT /api/pleroma/notification_settings` with `block_from_strangers`
/// set: a stranger's favourite and mention never reach the inbox, an
/// account the recipient follows back gets through the gate
/// (followers-need-not), and the documented exemption lets a stranger's
/// follow request land on a gated, locked account anyway.
#[tokio::test]
async fn the_stranger_gate_withholds_all_but_the_request() {
    let db = common::test_db().await;
    let pool = db.pool().clone();
    let app = common::test_app(pool.clone());
    let (_alice, alice_token) = user(&pool, "alice").await;
    let (bob, bob_token) = user(&pool, "bob").await;
    let (dave, dave_token) = user(&pool, "dave").await;
    let (eve, eve_token) = user(&pool, "eve").await;

    gate_strangers(&app, &alice_token, true).await;
    let own = got(
        &app,
        &alice_token,
        &format!("{ACCOUNTS}/verify_credentials"),
    )
    .await;
    assert_eq!(
        own["pleroma"]["notification_settings"]["block_from_strangers"],
        json!(true),
        "the own-view renders the stored flag"
    );

    let subject = entity_id(&post(&app, &alice_token, "gate me").await);
    let _withheld_like = status_action(&app, &bob_token, &subject, "favourite").await;
    let _withheld_mention = post(&app, &bob_token, "@alice can you hear me").await;
    assert!(
        flat(&app, &alice_token, "").await.is_empty(),
        "a stranger's like and mention are both withheld"
    );

    let followed = follow(&app, &alice_token, &dave.id.to_string()).await;
    assert_eq!(
        followed["following"],
        json!(true),
        "alice follows dave back"
    );
    let dave_id = dave.id.to_string();
    let _told_like = status_action(&app, &dave_token, &subject, "favourite").await;
    let dave_post = entity_id(&post(&app, &dave_token, "@alice now we talk").await);
    assert_eq!(
        sorted(told(&flat(&app, &alice_token, "").await)),
        sorted(vec![
            telling("favourite", &dave_id, Some(&subject)),
            telling("mention", &dave_id, Some(&dave_post)),
        ]),
        "the account alice follows reaches the inbox, and nothing of \
         bob's ever did"
    );

    lock_account(&app, &eve_token).await;
    gate_strangers(&app, &eve_token, true).await;
    let _requested = follow(&app, &bob_token, &eve.id.to_string()).await;
    assert_eq!(
        told(&flat(&app, &eve_token, "").await),
        vec![telling("follow_request", &bob.id.to_string(), None)],
        "the exempt follow request still lands on a gated, locked account"
    );
}

// ──────────────────  Scenario (5): conversations  ──────────────────

/// Whether the caller's single listed conversation stands unread.
async fn listed_unread(app: &Router, token: &str) -> bool {
    let mut page = got_array(app, token, CONVERSATIONS).await;
    assert_eq!(page.len(), 1, "one conversation is listed");
    page.remove(0)["unread"]
        .as_bool()
        .expect("unread is a boolean")
}

/// The account ids a conversation entity names, sorted for comparison.
fn participant_ids(entity: &Value) -> Vec<String> {
    sorted(
        entity["accounts"]
            .as_array()
            .expect("accounts is a list")
            .iter()
            .map(entity_id)
            .collect::<Vec<String>>(),
    )
}

/// One participant's conversation entity: the DM as `last_status` and
/// exactly `owed` as the other participants (never the viewer).
fn assert_participation(name: &str, entity: &Value, dm_id: &str, owed: Vec<String>) {
    assert_eq!(
        entity["last_status"]["id"],
        json!(dm_id),
        "{name} sees the DM as the thread's newest post"
    );
    assert_eq!(
        participant_ids(entity),
        sorted(owed),
        "{name}'s conversation names the other participants, never the viewer"
    );
}

/// A `direct` post @-mentioning two local users opens one conversation
/// all three list: each side carries its own participation id, the
/// thread's newest post as `last_status`, the other two participants as
/// `accounts` (never the viewer), the author's own side read and every
/// addressee's unread — and `recipients[]` filters the listing on exactly
/// those addressee lists.
#[tokio::test]
async fn a_direct_post_threads_the_three_participants() {
    let db = common::test_db().await;
    let pool = db.pool().clone();
    let app = common::test_app(pool.clone());
    let (alice, alice_token) = user(&pool, "alice").await;
    let (bob, bob_token) = user(&pool, "bob").await;
    let (carol, carol_token) = user(&pool, "carol").await;
    let dm = direct_post(&app, &alice_token, "@bob @carol psst").await;
    let dm_id = entity_id(&dm);

    let alices = got_array(&app, &alice_token, CONVERSATIONS).await;
    let bobs = got_array(&app, &bob_token, CONVERSATIONS).await;
    let carols = got_array(&app, &carol_token, CONVERSATIONS).await;
    assert_eq!(
        (alices.len(), bobs.len(), carols.len()),
        (1, 1, 1),
        "the thread stands once for each participant"
    );

    let (alice_id, bob_id, carol_id) = (
        alice.id.to_string(),
        bob.id.to_string(),
        carol.id.to_string(),
    );
    let mut parts = vec![
        entity_id(&alices[0]),
        entity_id(&bobs[0]),
        entity_id(&carols[0]),
    ];
    parts.sort();
    parts.dedup();
    assert_eq!(parts.len(), 3, "every side carries its own id");
    assert_eq!(
        alices[0]["unread"],
        json!(false),
        "the author's own post reads"
    );
    assert_eq!(
        bobs[0]["unread"],
        json!(true),
        "the first addressee owes it"
    );
    assert_eq!(carols[0]["unread"], json!(true), "and so does the second");
    assert_participation(
        "alice",
        &alices[0],
        &dm_id,
        vec![bob_id.clone(), carol_id.clone()],
    );
    assert_participation(
        "bob",
        &bobs[0],
        &dm_id,
        vec![alice_id.clone(), carol_id.clone()],
    );
    assert_participation("carol", &carols[0], &dm_id, vec![alice_id.clone(), bob_id]);

    let both = format!("?recipients={alice_id}&recipients={carol_id}");
    assert_eq!(
        ids_of(&got_array(&app, &bob_token, &format!("{CONVERSATIONS}{both}")).await),
        vec![entity_id(&bobs[0])],
        "bob's thread addresses alice and carol together"
    );
    assert!(
        got_array(
            &app,
            &bob_token,
            &format!("{CONVERSATIONS}?recipients={}", Uuid::now_v7())
        )
        .await
        .is_empty(),
        "an account nobody shares the thread with empties the listing"
    );
}

/// The scenario 5 seed: a `direct` post by alice @-mentioning bob and
/// carol, beside the three tokens and each side's participation id in the
/// thread it opened.
#[derive(Debug)]
struct Thread {
    /// Alice's token.
    alice: String,
    /// Bob's token.
    bob: String,
    /// Carol's token.
    carol: String,
    /// Alice's own participation id.
    alice_part: String,
    /// Bob's own participation id.
    bob_part: String,
    /// Carol's own participation id.
    carol_part: String,
}

/// Posts the opening DM through HTTP and reads each participant's side of
/// the thread back from their own listing.
async fn open_thread(app: &Router, pool: &PgPool) -> Thread {
    let (_alice, alice_token) = user(pool, "alice").await;
    let (_bob, bob_token) = user(pool, "bob").await;
    let (_carol, carol_token) = user(pool, "carol").await;
    let _dm = direct_post(app, &alice_token, "@bob @carol thread me").await;
    Thread {
        alice_part: entity_id(&got_array(app, &alice_token, CONVERSATIONS).await.remove(0)),
        bob_part: entity_id(&got_array(app, &bob_token, CONVERSATIONS).await.remove(0)),
        carol_part: entity_id(&got_array(app, &carol_token, CONVERSATIONS).await.remove(0)),
        alice: alice_token,
        bob: bob_token,
        carol: carol_token,
    }
}

/// A reply through `in_reply_to_conversation_id` joins the same thread for
/// everybody (forced `direct`, its recipients auto-addressed), and
/// Pleroma's `…/read` flips every unread participation at once, answering
/// exactly the rows that changed — the empty array when nothing is.
#[tokio::test]
async fn a_conversation_reply_joins_the_thread_and_read_all_flips_the_sides() {
    let db = common::test_db().await;
    let pool = db.pool().clone();
    let app = common::test_app(pool.clone());
    let thread = open_thread(&app, &pool).await;

    let reply = posted(
        &app,
        &thread.carol,
        STATUSES,
        &json!({ "status": "aye", "in_reply_to_conversation_id": thread.carol_part }),
    )
    .await;
    let reply_id = entity_id(&reply);
    assert_eq!(
        reply["visibility"],
        json!("direct"),
        "the reply is forced direct"
    );

    let alices = got_array(&app, &thread.alice, CONVERSATIONS).await;
    assert_eq!(
        entity_id(&alices[0]),
        thread.alice_part,
        "the reply joined the same thread, not a new one"
    );
    assert_eq!(
        alices[0]["last_status"]["id"],
        json!(reply_id),
        "and the reply is its newest post"
    );
    assert_eq!(alices[0]["unread"], json!(true), "alice owes it");

    let flipped = acted(
        &app,
        &thread.alice,
        &format!("{PLEROMA_CONVERSATIONS}/read"),
    )
    .await;
    let rows = flipped
        .as_array()
        .expect("the read-all answers an array")
        .clone();
    assert_eq!(
        rows.len(),
        1,
        "exactly the one unread participation flipped"
    );
    assert_eq!(
        entity_id(&rows[0]),
        thread.alice_part,
        "the caller's own row"
    );
    assert_eq!(rows[0]["unread"], json!(false), "now read");
    assert_eq!(
        acted(
            &app,
            &thread.alice,
            &format!("{PLEROMA_CONVERSATIONS}/read")
        )
        .await,
        json!([]),
        "and an empty second pass flips nothing"
    );
}

/// `DELETE /api/v1/conversations/{id}` withdraws only its owner's side: a
/// stranger's id is the shared 404, the owner's listing empties, the other
/// participants keep listing the thread — newest post included — and the
/// thread's statuses stay readable to them.
#[tokio::test]
async fn a_conversation_delete_withdraws_only_the_owners_side() {
    let db = common::test_db().await;
    let pool = db.pool().clone();
    let app = common::test_app(pool.clone());
    let thread = open_thread(&app, &pool).await;
    let reply = posted(
        &app,
        &thread.carol,
        STATUSES,
        &json!({ "status": "aye", "in_reply_to_conversation_id": thread.carol_part }),
    )
    .await;
    let reply_id = entity_id(&reply);

    let foreign = common::TestRequest::delete(&format!("{CONVERSATIONS}/{}", thread.carol_part))
        .bearer(&thread.bob)
        .send(&app)
        .await;
    common::assert_answer(&foreign, StatusCode::NOT_FOUND, "a stranger's withdrawal");
    common::assert_error(&foreign, NOT_FOUND, "the foreign participation id");

    assert_eq!(
        withdrawn(
            &app,
            &thread.carol,
            &format!("{CONVERSATIONS}/{}", thread.carol_part)
        )
        .await,
        json!({}),
        "the withdrawal answers the empty object"
    );
    assert!(
        got_array(&app, &thread.carol, CONVERSATIONS)
            .await
            .is_empty(),
        "carol's own side is gone"
    );
    let bobs = got_array(&app, &thread.bob, CONVERSATIONS).await;
    assert_eq!(
        ids_of(&bobs),
        vec![thread.bob_part],
        "bob keeps listing exactly his one participation"
    );
    assert_eq!(
        bobs[0]["last_status"]["id"],
        json!(reply_id),
        "with carol's reply as the newest post"
    );
    common::assert_answer(
        &common::TestRequest::get(&format!("{STATUSES}/{reply_id}"))
            .bearer(&thread.alice)
            .send(&app)
            .await,
        StatusCode::OK,
        "the statuses survive the withdrawal as readable posts",
    );
}

// ──────────────────────  Scenario (6): chats  ──────────────────────

/// The `POST /api/v1/pleroma/chats/by-account-id/{id}` that gets or
/// creates the caller's chat with `peer`, answered as the `Chat` entity.
async fn open_chat(app: &Router, token: &str, peer: &str) -> Value {
    acted(app, token, &format!("{CHATS}/by-account-id/{peer}")).await
}

/// The `POST /api/v1/pleroma/chats/{id}/messages` with `content`, answered
/// as the sender's `ChatMessage` entity.
async fn send_message(app: &Router, token: &str, chat: &str, text: &str) -> Value {
    posted(
        app,
        token,
        &format!("{CHATS}/{chat}/messages"),
        &json!({ "content": text }),
    )
    .await
}

/// The `GET /api/v1/pleroma/chats/{id}`, answered as the `Chat` entity.
async fn show_chat(app: &Router, token: &str, chat: &str) -> Value {
    got(app, token, &format!("{CHATS}/{chat}")).await
}

/// The `GET` of `root` (either chat list) as the caller's one listed chat.
async fn listed_chat(app: &Router, token: &str, root: &str) -> Value {
    let mut page = got_array(app, token, root).await;
    assert_eq!(page.len(), 1, "{root} carries the caller's one chat");
    page.remove(0)
}

/// The `GET /api/v1/pleroma/chats/{id}/messages`, newest reference first.
async fn chat_messages(app: &Router, token: &str, chat: &str) -> Vec<Value> {
    got_array(app, token, &format!("{CHATS}/{chat}/messages")).await
}

/// The `unread` count of the caller's chat `id`, through its show read.
async fn chat_unread(app: &Router, token: &str, chat: &str) -> i64 {
    show_chat(app, token, chat).await["unread"]
        .as_i64()
        .expect("unread is a number")
}

/// Two local users exchange chat messages and every per-peer read — the
/// v1 list, the v2 list and the show — agrees on the same `unread` count
/// as the other side's view: alice's message is bob's one owed and bob's
/// reply is alice's, the sender never owes their own post, and each chat
/// names the other participant.
#[tokio::test]
async fn a_chat_pair_agrees_on_the_peers_unread_counts() {
    let db = common::test_db().await;
    let pool = db.pool().clone();
    let app = common::test_app(pool.clone());
    let (alice, alice_token) = user(&pool, "alice").await;
    let (bob, bob_token) = user(&pool, "bob").await;
    let alice_id = alice.id.to_string();
    let bob_id = bob.id.to_string();

    let hers = open_chat(&app, &alice_token, &bob_id).await;
    let restated = open_chat(&app, &alice_token, &bob_id).await;
    assert_eq!(restated, hers, "opening the same chat twice restates it");
    let her_chat = entity_id(&hers);
    let his_chat = entity_id(&open_chat(&app, &bob_token, &alice_id).await);
    assert_ne!(her_chat, his_chat, "each participant holds their own row");
    assert_eq!(hers["account"]["id"], json!(bob_id), "hers names bob");
    assert_eq!(hers["unread"], json!(0), "a fresh chat owes nothing");
    assert_eq!(
        show_chat(&app, &bob_token, &his_chat).await["account"]["id"],
        json!(alice_id),
        "and his names alice"
    );

    let first = send_message(&app, &alice_token, &her_chat, "hi from alice").await;
    assert_eq!(
        first["content"],
        json!("<p>hi from alice</p>"),
        "rendered, from her"
    );
    assert_eq!(first["account_id"], json!(alice_id), "under her account");
    assert_eq!(
        first["unread"],
        json!(false),
        "the sender has read what they wrote"
    );
    assert_eq!(
        chat_unread(&app, &bob_token, &his_chat).await,
        1,
        "bob owes it"
    );
    assert_eq!(
        listed_chat(&app, &bob_token, CHATS).await["unread"],
        json!(1),
        "the v1 list agrees"
    );
    assert_eq!(
        listed_chat(&app, &bob_token, CHATS_V2).await["unread"],
        json!(1),
        "and the v2 list"
    );
    assert_eq!(
        chat_unread(&app, &alice_token, &her_chat).await,
        0,
        "alice owes nothing yet"
    );

    let _second = send_message(&app, &bob_token, &his_chat, "hi back").await;
    assert_eq!(
        chat_unread(&app, &alice_token, &her_chat).await,
        1,
        "the reply lands unread for alice"
    );
    assert_eq!(
        chat_unread(&app, &bob_token, &his_chat).await,
        1,
        "and alice's message is still owed"
    );
    assert_eq!(
        chat_messages(&app, &alice_token, &her_chat)
            .await
            .iter()
            .map(|message| message["unread"].clone())
            .collect::<Vec<Value>>(),
        vec![json!(true), json!(false)],
        "newest first: bob's reply owed, her own read"
    );
}

/// `carol` neither lists nor reads the pair's chats nor posts into them:
/// both lists stay empty and every probe of `her_chat` is the shared 404.
async fn assert_stranger_locked_out(app: &Router, carol_token: &str, her_chat: &str) {
    assert!(
        got_array(app, carol_token, CHATS).await.is_empty(),
        "carol lists no chats"
    );
    assert!(
        got_array(app, carol_token, CHATS_V2).await.is_empty(),
        "on either list"
    );
    for path in [
        format!("{CHATS}/{her_chat}"),
        format!("{CHATS}/{her_chat}/messages"),
    ] {
        let refused = common::TestRequest::get(&path)
            .bearer(carol_token)
            .send(app)
            .await;
        common::assert_answer(
            &refused,
            StatusCode::NOT_FOUND,
            "carol's read of their chat",
        );
        common::assert_error(&refused, NOT_FOUND, &path);
    }
    let posting = common::TestRequest::post(&format!("{CHATS}/{her_chat}/messages"))
        .bearer(carol_token)
        .json(&json!({ "content": "let me in" }))
        .send(app)
        .await;
    common::assert_answer(
        &posting,
        StatusCode::NOT_FOUND,
        "carol's post into their chat",
    );
    common::assert_error(&posting, NOT_FOUND, "the foreign chat id");
}

/// The chat read endpoint moves the caller's marker only up to the posted
/// `last_read_id` — the count steps down, then empties — and a third user
/// neither lists nor reads the pair's chats nor posts into them.
#[tokio::test]
async fn the_chat_read_empties_the_count_and_a_stranger_is_locked_out() {
    let db = common::test_db().await;
    let pool = db.pool().clone();
    let app = common::test_app(pool.clone());
    let (alice, alice_token) = user(&pool, "alice").await;
    let (bob, bob_token) = user(&pool, "bob").await;
    let (_carol, carol_token) = user(&pool, "carol").await;
    let her_chat = entity_id(&open_chat(&app, &alice_token, &bob.id.to_string()).await);
    let his_chat = entity_id(&open_chat(&app, &bob_token, &alice.id.to_string()).await);

    let _first = send_message(&app, &alice_token, &her_chat, "one").await;
    let _second = send_message(&app, &bob_token, &his_chat, "two").await;
    let _third = send_message(&app, &alice_token, &her_chat, "three").await;
    assert_eq!(
        chat_unread(&app, &bob_token, &his_chat).await,
        2,
        "bob owes alice's one and three"
    );

    let refs = ids_of(&chat_messages(&app, &bob_token, &his_chat).await);
    assert_eq!(refs.len(), 3, "three references, newest first");
    let partial = posted(
        &app,
        &bob_token,
        &format!("{CHATS}/{his_chat}/read"),
        &json!({ "last_read_id": refs[2] }),
    )
    .await;
    assert_eq!(
        partial["unread"],
        json!(1),
        "the marker stops at the oldest owed message"
    );
    assert_eq!(
        chat_unread(&app, &bob_token, &his_chat).await,
        1,
        "and the count follows"
    );

    let full = posted(
        &app,
        &bob_token,
        &format!("{CHATS}/{his_chat}/read"),
        &json!({ "last_read_id": refs[0] }),
    )
    .await;
    assert_eq!(
        full["unread"],
        json!(0),
        "walking the marker to the newest empties it"
    );
    assert_eq!(
        chat_messages(&app, &bob_token, &his_chat)
            .await
            .iter()
            .filter(|message| message["unread"].as_bool().expect("a flag"))
            .count(),
        0,
        "no reference is unread anymore"
    );

    assert_stranger_locked_out(&app, &carol_token, &her_chat).await;
}
